import{_ as i,C as a,o as r,c as n,j as t,a as l,E as s,al as d}from"./chunks/framework.7vp1BMOE.js";const c="/px4_user_guide/assets/siyi-unifc-6-pico-top.DiyTUizW.png",p="/px4_user_guide/assets/siyi-unifc-6-pico-pinout.3M1Crzo2.png",C=JSON.parse('{"title":"SIYI UniFC 6 PICO","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/siyi-unifc-6-pico.md","filePath":"en/flight_controller/siyi-unifc-6-pico.md"}'),u={name:"en/flight_controller/siyi-unifc-6-pico.md"};function h(g,e,m,f,b,S){const o=a("Badge");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"siyi-unifc-6-pico",tabindex:"-1"},[l("SIYI UniFC 6 PICO "),t("a",{class:"header-anchor",href:"#siyi-unifc-6-pico","aria-label":'Permalink to "SIYI UniFC 6 PICO"'},"​")],-1)),s(o,{type:"tip",text:"PX4 main (v2.0)"}),e[1]||(e[1]=d('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://siyi.biz/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>SIYI UniFC 6 PICO</em> is a flight controller designed by SIYI Technology. It features high-performance sensors, dual CAN bus, Ethernet connectivity, and extensive I/O options.</p><img src="'+c+'"><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>MCU:</strong> STM32H743II (32 Bit Arm® Cortex®-M7, 480 MHz, 2MB Flash, 1MB RAM)</li><li><strong>IMU (Dual):</strong> TDK InvenSense ICM-45686 (primary, SPI4) + Bosch BMI088 accel/gyro (secondary, SPI1)</li><li><strong>Barometer (Dual):</strong> InvenSense ICP201XX (internal at address 0x63, external at address 0x64)</li><li><strong>Magnetometer:</strong> iSentek IST8310</li><li><strong>Interfaces:</strong><ul><li>6x UARTs (including GPS, telemetry, and RC ports)</li><li>2x CAN (DroneCAN / UAVCAN)</li><li>4x I²C (2 external, 2 internal)</li><li>1x dedicated RC Input (SBUS / DSM / SUMD)</li><li>14x PWM outputs (DShot-capable)</li><li>SDMMC1 4-bit Micro-SD slot (high-speed logging)</li><li>Ethernet (RMII, LAN8742A PHY)</li><li>USB</li><li>Onboard safety button</li></ul></li><li><strong>Power:</strong><ul><li>Single analog battery voltage/current channel (BAT1)</li><li>Voltage sensing up to 14S LiPo by default</li><li>On-board BECs for peripheral power (consult manufacturer for exact rail specifications)</li></ul></li></ul><h2 id="where-to-buy" tabindex="-1">Where to Buy <a class="header-anchor" href="#where-to-buy" aria-label="Permalink to &quot;Where to Buy&quot;">​</a></h2><p>Order from <a href="https://siyi.biz/" target="_blank" rel="noreferrer">SIYI</a>.</p><h2 id="physical-mechanical" tabindex="-1">Physical / Mechanical <a class="header-anchor" href="#physical-mechanical" aria-label="Permalink to &quot;Physical / Mechanical&quot;">​</a></h2><ul><li>Weight: 37.9g</li><li>Dimensions: 49.0 x 42.6 x 16.2mm</li><li>Operating temperature: -20 ~ 85°C</li></ul><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h2><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li><strong>FMU Processor:</strong> STM32H743II <ul><li>32 Bit Arm® Cortex®-M7, 480 MHz</li><li>2MB Flash, 1MB RAM</li></ul></li><li><strong>On-board Sensors:</strong><ul><li>Accel/Gyro 1: TDK InvenSense ICM-45686 (SPI4)</li><li>Accel/Gyro 2: Bosch BMI088 (SPI1)</li><li>Barometer 1: InvenSense ICP201XX (I²C3, address <code>0x63</code>)</li><li>Barometer 2: InvenSense ICP201XX (I²C2, address <code>0x64</code>)</li><li>Compass: iSentek IST8310 (I²C3, address <code>0x0E</code>)</li></ul></li></ul><h3 id="power-configuration" tabindex="-1">Power Configuration <a class="header-anchor" href="#power-configuration" aria-label="Permalink to &quot;Power Configuration&quot;">​</a></h3><p>The board provides <strong>one analog battery monitoring channel</strong>:</p><ul><li><strong>BAT1</strong> - Battery voltage and current sensed on <code>ADC1_INP6</code> (voltage, PF12) and <code>ADC1_INP2</code> (current, PF11).</li></ul><p>The channel feeds PX4&#39;s standard analog battery driver with a default 18.181 voltage divider and 36.366 A/V current ratio, supporting up to 14S LiPo batteries out of the box.</p><h2 id="connectors-pinouts" tabindex="-1">Connectors &amp; Pinouts <a class="header-anchor" href="#connectors-pinouts" aria-label="Permalink to &quot;Connectors &amp; Pinouts&quot;">​</a></h2><p>The following image shows the port connection details, including RC, UARTs, CAN, I2C, PWM, and LAN connections.</p><img src="'+p+'"><p>The board exposes the following connectors and solder pads:</p><ul><li><code>TELEM1</code> (6-pin) - primary MAVLink radio link (USART2)</li><li><code>TELEM2</code> (6-pin) - companion computer / secondary MAVLink (USART6)</li><li><code>GPS1</code> (10-pin JST-GH) - UBX / NMEA GPS (USART1)</li><li><code>GPS2</code> (6-pin) - secondary GPS (UART4)</li><li><code>USART3</code> (4-pin) - generic auxiliary UART breakout (USART3)</li><li><code>RCIN</code> (3-pin) - SBUS / DSM / SUMD receiver input (UART8)</li><li><code>CAN1</code> (4-pin) - FDCAN1 (DroneCAN / UAVCAN)</li><li><code>CAN2</code> (4-pin) - FDCAN2 (DroneCAN / UAVCAN)</li><li><code>I2C</code> (4-pin) - external I²C</li><li><code>PWM</code> - 14 PWM outputs (M1–M14)</li><li><code>LAN</code> (4-pin) - Ethernet (RMII data channels only)</li></ul><h3 id="standard-serial-port-mapping" tabindex="-1">Standard Serial Port Mapping <a class="header-anchor" href="#standard-serial-port-mapping" aria-label="Permalink to &quot;Standard Serial Port Mapping&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Physical UART</th><th>PCB Silk Label</th><th>PX4 Slot (QGC)</th><th>Default Usage</th></tr></thead><tbody><tr><td>USART1</td><td><code>GPS1</code></td><td>GPS 1</td><td>GPS</td></tr><tr><td>USART2</td><td><code>TELEM1</code></td><td>TELEM 1</td><td>MAVLink (Primary)</td></tr><tr><td>USART3</td><td><code>USART3</code></td><td>TELEM 3</td><td>User Auxiliary</td></tr><tr><td>UART4</td><td><code>GPS2</code></td><td>GPS 2</td><td>Secondary GPS</td></tr><tr><td>USART6</td><td><code>TELEM2</code></td><td>TELEM 2</td><td>MAVLink (Companion)</td></tr><tr><td>UART8</td><td><code>RCIN</code></td><td>RC</td><td>RC Input (SBUS/DSM/SUMD)</td></tr></tbody></table><h3 id="debug-port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug-port" aria-label="Permalink to &quot;Debug Port&quot;">​</a></h3><p>The NSH console is exposed over USB CDC out of the box and is available via QGroundControl&#39;s MAVLink Console.</p><h3 id="rc-input" tabindex="-1">RC Input <a class="header-anchor" href="#rc-input" aria-label="Permalink to &quot;RC Input&quot;">​</a></h3><p>RC Input is mapped to <strong>UART8</strong> through the dedicated <code>RCIN</code> connector.</p><p>Only the receive line (<code>RX8</code>) is broken out, so the port supports:</p><ul><li>Single-wire SBUS (inverted)</li><li>Spektrum DSM</li><li>Graupner SUMD</li></ul><p>Configure the receiver protocol with the relevant <code>RC_*_PRT_CFG</code> parameter from QGroundControl, pointing it at the <code>RC</code> slot.</p><h3 id="pwm-output-groups" tabindex="-1">PWM Output Groups <a class="header-anchor" href="#pwm-output-groups" aria-label="Permalink to &quot;PWM Output Groups&quot;">​</a></h3><p>The 14 PWM outputs are organized into four timer groups. Channels in the same group must use the same output rate and DShot mode:</p><table tabindex="0"><thead><tr><th>Group</th><th>Timer</th><th>Channels</th></tr></thead><tbody><tr><td>1</td><td>TIM1</td><td>M1–M4</td></tr><tr><td>2</td><td>TIM4</td><td>M5–M8</td></tr><tr><td>3</td><td>TIM5</td><td>M9–M12</td></tr><tr><td>4</td><td>TIM12</td><td>M13–M14</td></tr></tbody></table><p>Channels within the same group need to use the same output rate. If any channel in a group uses DShot then all channels in the group need to use DShot.</p><h3 id="ethernet" tabindex="-1">Ethernet <a class="header-anchor" href="#ethernet" aria-label="Permalink to &quot;Ethernet&quot;">​</a></h3><p>The board features an Ethernet port with RMII interface (LAN8742A PHY). Only the four RMII data channels are broken out to external pins: RMII_RXD0, RMII_RXD1, RMII_TXD0, RMII_TXD1. Other RMII signals (REF_CLK, CRS_DV, MDC, MDIO) are connected internally to the onboard PHY chip. MAVLink is pre-configured on Ethernet interface (MAV_2_CONFIG set to 1000).</p><h2 id="building-loading-firmware" tabindex="-1">Building / Loading Firmware <a class="header-anchor" href="#building-loading-firmware" aria-label="Permalink to &quot;Building / Loading Firmware&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware (from PX4 v2.0). It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target from source:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> siyi_unifc-6-pico_default</span></span></code></pre></div><p>Initial firmware flashing can be done over USB via QGroundControl. The bootloader status does not follow the standard generic PX4 LED indications (Green = Bootloader / Error, Blue = Active / Activity, Red = Powered).</p>',42))])}const M=i(u,[["render",h]]);export{C as __pageData,M as default};
